"""Ledger parsing and reporting."""

import datetime
import decimal
import re
from dataclasses import dataclass
from decimal import Decimal
from typing import Dict, Iterable, List, Optional

_DATE_RE = re.compile(r"(\d{4})-(\d{2})-(\d{2})", re.ASCII)
_AMOUNT_RE = re.compile(r"([+-]?)(\d+)(?:\.(\d{1,2}))?", re.ASCII)
_CATEGORY_RE = re.compile(r"\S+")
# date, category, amount, optional note; fields separated by spaces/tabs.
_LINE_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL)


class ParseError(ValueError):
    """A line of the ledger (or an entry being added) is not valid."""

    def __init__(self, line: int, message: str) -> None:
        self.line = line
        self.reason = message
        super().__init__("line {}: {}".format(line, message))


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def _parse_date(text: str) -> datetime.date:
    m = _DATE_RE.fullmatch(text)
    if not m:
        raise ValueError("invalid date {!r} (expected YYYY-MM-DD)".format(text))
    try:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise ValueError("date {!r} does not exist".format(text)) from None


def _parse_amount(text: str) -> Decimal:
    m = _AMOUNT_RE.fullmatch(text)
    if not m:
        raise ValueError(
            "invalid amount {!r} (expected a number with at most two decimals)".format(text)
        )
    sign, whole, frac = m.group(1), m.group(2), (m.group(3) or "")
    # Build the exact two-decimal value without depending on context precision.
    value = Decimal("{}{}.{}".format(sign, whole, frac.ljust(2, "0")))
    if value == 0:
        value = Decimal("0.00")  # never keep a negative zero
    return value


def _parse_category(text: str) -> str:
    if not _CATEGORY_RE.fullmatch(text):
        raise ValueError("invalid category {!r} (must be a single word)".format(text))
    return text.lower()


def make_entry(date: str, category: str, amount: str, note: str = "") -> Entry:
    """Build an Entry from its textual fields, validating each one.

    Raises ValueError with a description of the problem.
    """
    note = (note or "").strip()
    if "\n" in note or "\r" in note:
        raise ValueError("note must be on a single line")
    return Entry(_parse_date(date), _parse_category(category), _parse_amount(amount), note)


def parse(text: str) -> List[Entry]:
    """Parse ledger text into a list of entries, in file order."""
    entries = []
    for number, raw in enumerate(text.split("\n"), start=1):
        if raw.endswith("\r"):
            raw = raw[:-1]
        stripped = raw.strip()
        if not stripped or stripped.startswith("#"):
            continue
        m = _LINE_RE.fullmatch(raw.strip(" \t"))
        if not m:
            raise ParseError(
                number, "expected 'DATE CATEGORY AMOUNT [NOTE]', got {!r}".format(stripped)
            )
        try:
            entries.append(make_entry(m.group(1), m.group(2), m.group(3), m.group(4) or ""))
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
    return entries


def _total(amounts: Iterable[Decimal]) -> Decimal:
    with decimal.localcontext() as ctx:
        ctx.prec = decimal.MAX_PREC
        total = Decimal("0.00")
        for amount in amounts:
            total += amount
        return total


def balance(entries: Iterable[Entry]) -> Decimal:
    """Total of all amounts."""
    return _total(e.amount for e in entries)


def _group(entries: Iterable[Entry], key) -> Dict[str, Decimal]:
    groups: Dict[str, List[Decimal]] = {}
    for e in entries:
        groups.setdefault(key(e), []).append(e.amount)
    return {name: _total(amounts) for name, amounts in groups.items()}


def by_category(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    """Total per category."""
    return _group(entries, lambda e: e.category)


def by_month(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    """Total per month, keyed like '2024-03'."""
    return _group(entries, lambda e: "{:04d}-{:02d}".format(e.date.year, e.date.month))


def filter_entries(
    entries: Iterable[Entry],
    category: Optional[str] = None,
    since: Optional[datetime.date] = None,
    until: Optional[datetime.date] = None,
) -> List[Entry]:
    """Entries matching all given criteria (inclusive dates, case-insensitive category)."""
    wanted = category.lower() if category is not None else None
    result = []
    for e in entries:
        if wanted is not None and e.category != wanted:
            continue
        if since is not None and e.date < since:
            continue
        if until is not None and e.date > until:
            continue
        result.append(e)
    return result


def format_amount(amount: Decimal) -> str:
    """Format an amount with exactly two decimals."""
    text = "{:.2f}".format(amount)
    if text.startswith("-") and Decimal(text) == 0:
        text = text[1:]
    return text


def format_entry(entry: Entry) -> str:
    """Format an entry as a ledger line: DATE CATEGORY AMOUNT [NOTE]."""
    parts = [entry.date.isoformat(), entry.category, format_amount(entry.amount)]
    if entry.note:
        parts.append(entry.note)
    return " ".join(parts)
