"""Command-line interface for pennywise."""

import argparse
import csv
import datetime
import json
import os
import sys
from typing import List, Optional

from .core import (
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    make_entry,
    parse,
)

PROG = "pennywise"


class _ReadError(Exception):
    pass


def _date_arg(text: str) -> datetime.date:
    try:
        return datetime.datetime.strptime(text, "%Y-%m-%d").date() if _strict_date(text) else _bad()
    except ValueError:
        raise argparse.ArgumentTypeError("invalid date {!r} (expected YYYY-MM-DD)".format(text))


def _strict_date(text: str) -> bool:
    return (
        len(text) == 10
        and text[4] == "-"
        and text[7] == "-"
        and (text[:4] + text[5:7] + text[8:]).isascii()
        and (text[:4] + text[5:7] + text[8:]).isdigit()
    )


def _bad():
    raise ValueError


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog=PROG, description="Tell you where the money in your ledger went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    p = sub.add_parser("balance", help="print the total of all entries")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print matching entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to the ledger")
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=["csv"], default="csv")

    return parser


def _read_ledger(path: str) -> str:
    try:
        if path == "-":
            data = sys.stdin.buffer.read()
        else:
            with open(path, "rb") as fh:
                data = fh.read()
        return data.decode("utf-8-sig")
    except OSError as exc:
        raise _ReadError("cannot read {}: {}".format(path, exc.strerror or exc))
    except UnicodeDecodeError:
        raise _ReadError("cannot read {}: not valid UTF-8 text".format(path))


def _sorted(entries):
    return sorted(entries, key=lambda e: e.date)  # stable: same-day keeps file order


def _entry_dict(e):
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def _cmd_balance(args, entries, out):
    total = format_amount(balance(entries))
    if args.json:
        out.append(json.dumps({"balance": total}))
    else:
        out.append(total)


def _cmd_summary(args, entries, out):
    groups = by_month(entries) if args.by == "month" else by_category(entries)
    names = sorted(groups)
    if args.json:
        out.append(json.dumps({n: format_amount(groups[n]) for n in names}))
    else:
        out.extend("{}  {}".format(n, format_amount(groups[n])) for n in names)


def _cmd_list(args, entries, out):
    chosen = _sorted(
        filter_entries(entries, category=args.category, since=args.since, until=args.until)
    )
    if args.json:
        out.append(json.dumps([_entry_dict(e) for e in chosen]))
    else:
        out.extend(format_entry(e) for e in chosen)


def _cmd_export(args, entries, out):
    import io

    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _sorted(entries):
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    out.append(buf.getvalue().rstrip("\n"))


def _count_lines(data: bytes) -> int:
    if not data:
        return 0
    return data.count(b"\n") + (0 if data.endswith(b"\n") else 1)


def _cmd_add(args) -> int:
    path = args.file
    try:
        with open(path, "rb") as fh:
            existing = fh.read()
    except FileNotFoundError:
        existing = b""
    except OSError as exc:
        _error("cannot read {}: {}".format(path, exc.strerror or exc))
        return 2

    line_no = _count_lines(existing) + 1
    try:
        entry = make_entry(args.date, args.category, args.amount, args.note)
    except ValueError as exc:
        _error("{}: {}".format(path, ParseError(line_no, str(exc))))
        return 1

    line = format_entry(entry)
    prefix = b"" if not existing or existing.endswith(b"\n") else b"\n"
    try:
        with open(path, "ab") as fh:
            fh.write(prefix + line.encode("utf-8") + b"\n")
    except OSError as exc:
        _error("cannot write {}: {}".format(path, exc.strerror or exc))
        return 2
    print(line)
    return 0


def _error(message: str) -> None:
    print("{}: error: {}".format(PROG, message), file=sys.stderr)


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
}


def main(argv: Optional[List[str]] = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2

    if args.command == "add":
        return _cmd_add(args)

    try:
        text = _read_ledger(args.file)
    except _ReadError as exc:
        _error(str(exc))
        return 2
    try:
        entries = parse(text)
    except ParseError as exc:
        name = "<stdin>" if args.file == "-" else args.file
        _error("{}: {}".format(name, exc))
        return 1

    out: List[str] = []
    _COMMANDS[args.command](args, entries, out)
    if out:
        try:
            sys.stdout.write("\n".join(out) + "\n")
            sys.stdout.flush()
        except BrokenPipeError:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
    return 0


if __name__ == "__main__":
    sys.exit(main())
